window.__GUIDE_CHUNKS__.push([{"id": "15-008", "chapter_num": 15, "chapter_title": "Renting and Buying a Home", "chapter_file": "15-renting-and-buying-a-home.md", "number": 8, "title": "Put down twenty percent or budget for mortgage default insurance", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing to learn; the premium is added to the mortgage if you need it.", "plain": "If your down payment is less than a fifth of the purchase price, federal rules require mortgage default insurance. The premium is a percentage of the mortgage amount and is usually added to the loan — it protects the lender, not you, so a bigger down payment is still the cheaper path.", "benefit_text": "Premiums range from 0.6% to 4.5% of the mortgage amount depending on the down payment; knowing the brackets lets you price the true cost of a small down payment before you commit.", "sources": "CMHC mortgage loan insurance — https://www.cmhc-schl.gc.ca/observer/2025/cmhc-mortgage-loan-insurance-explained", "notes": "", "urls": ["https://www.cmhc-schl.gc.ca/observer/2025/cmhc-mortgage-loan-insurance-explained"]}, {"id": "16-001", "chapter_num": 16, "chapter_title": "Living with a chronic disease", "chapter_file": "16-living-with-chronic-disease.md", "number": 1, "title": "Take your pills as prescribed; do not adjust the dose yourself", "money": "0", "time": "low", "willpower": "yes", "benefit": "high", "dimension": "death", "evidence": "B (disputed)", "grade": "B", "disputed": true, "cost": "Nothing beyond what the drugs already cost. The price is discipline: the same pills, at the same time, every day.", "plain": "People who take their medication on schedule tend to live longer. But read the fine print: people who keep a pill routine also tend to smoke less, move more, and keep their appointments. The routine marks a careful person as much as it delivers a drug. Either way, the trials that proved each drug worked all used full doses taken on schedule.", "benefit_text": "A pooled analysis in BMJ (2006): good adherence to medication was linked to lower mortality (OR 0.56, 95% CI 0.50 to 0.63) — and good adherence to placebo showed the same link (OR 0.56, 95% CI 0.43 to 0.74), the \"healthy adherer\" effect. For high blood pressure and diabetes specifically, skipped doses are directly tied to strokes, heart attacks, and kidney failure — UNVERIFIED in this edition (not stated in the cited meta-analysis; see docs/verification/spot-read.md).", "sources": "https://doi.org/10.1136/bmj.38875.675486.55", "notes": "Disputed only in the sense that no one can split how much of the survival gap is the drug and how much is the person. The safe reading stands: take what was prescribed, exactly as prescribed, and talk to your doctor before changing anything.", "urls": ["https://doi.org/10.1136/bmj.38875.675486.55"]}, {"id": "16-002", "chapter_num": 16, "chapter_title": "Living with a chronic disease", "chapter_file": "16-living-with-chronic-disease.md", "number": 2, "title": "Drink enough water to keep kidney stones from coming back", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free — tap water does the job. It takes some resolve to keep drinking all day, every day.", "plain": "Kidney stones come back less often when you drink more water. In a five-year trial, stone formers who pushed their fluids hard enough to make plenty of urine each day had far fewer recurrences than stone formers who changed nothing.", "benefit_text": "Borghi et al., 1996: 199 first-time calcium-stone formers were assigned to high water intake (enough for at least 2 litres of urine a day — volume target UNVERIFIED, not stated in the abstract; see docs/verification/spot-read.md) or no intervention. After 5 years, 12.1% of the high-water group had a recurrence versus 27.0% of the control group. PMID 8583588.", "sources": "https://pubmed.ncbi.nlm.nih.gov/8583588/", "notes": "", "urls": ["https://pubmed.ncbi.nlm.nih.gov/8583588/"]}, {"id": "16-003", "chapter_num": 16, "chapter_title": "Living with a chronic disease", "chapter_file": "16-living-with-chronic-disease.md", "number": 3, "title": "Treat gout to a target instead of chasing flares", "money": "low", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "A daily prescription pill, usually covered by provincial drug plans, plus regular blood tests to check uric acid.", "plain": "Gout is not just a sore toe now and then; the crystals keep damaging joints between flares. The fix is lowering uric acid below a set level and holding it there, with allopurinol as the usual first drug. Before starting it, people of Southeast Asian and African descent should get a gene test, because a dangerous reaction to the drug runs in those groups.", "benefit_text": "The 2020 American College of Rheumatology guideline: treat to a target serum urate under 6 mg/dL; allopurinol is the preferred first-line urate-lowering drug for everyone, including people with moderate-to-severe kidney disease; test for the HLA-B*58:01 variant before starting allopurinol in people of Southeast Asian descent (for example Han Chinese, Korean, Thai) and people who are African American, because carriers face a much higher risk of a severe skin reaction.", "sources": "https://acrjournals.onlinelibrary.wiley.com/doi/10.1002/acr.24180", "notes": "", "urls": ["https://acrjournals.onlinelibrary.wiley.com/doi/10.1002/acr.24180"]}, {"id": "16-004", "chapter_num": 16, "chapter_title": "Living with a chronic disease", "chapter_file": "16-living-with-chronic-disease.md", "number": 4, "title": "Get your eyes checked on the diabetes schedule", "money": "low", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "A dilated eye exam, covered for people with diabetes in Ontario and Quebec; an hour or two once every year or two.", "plain": "Diabetes can damage the eyes for years without any symptom. The schedule is simple: a full dilated eye exam within five years of a type 1 diagnosis, right at diagnosis for type 2, then every one to two years once the eyes look clear.", "benefit_text": "American Diabetes Association Standards of Care 2026: first dilated eye exam at diagnosis for type 2 diabetes and within 5 years of onset for type 1; if no diabetic retinopathy is found, repeat every 1 to 2 years. DOI 10.2337/dc26-S012.", "sources": "https://doi.org/10.2337/dc26-S012", "notes": "", "urls": ["https://doi.org/10.2337/dc26-S012"]}, {"id": "16-005", "chapter_num": 16, "chapter_title": "Living with a chronic disease", "chapter_file": "16-living-with-chronic-disease.md", "number": 5, "title": "Never swap a proven treatment for a supplement", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "C", "grade": "C", "disputed": false, "cost": "Free — it is about not buying things. It takes some resolve when a bottle promises an easy fix.", "plain": "In Canada, natural health products are not held to the same proof standard as prescription drugs. A supplement can reach the shelf on the basis of traditional use alone. Never drop a proven treatment for a bottle that claims to do the same job.", "benefit_text": "Health Canada's own information kit for natural health products says manufacturers may support a product with evidence \"ranging from clinical trial data to ... traditional resources\" — a deliberately lighter bar than the safety-and-efficacy trials required for prescription drugs. A CMAJ editorial described the separate track with minimal pre-market requirements. The conditions people most want to \"treat naturally\" — high blood pressure, diabetes, cancer — are exactly the ones where stopping real treatment causes strokes, coma, and death.", "sources": "http://www.canada.ca/en/health-canada/services/drugs-health-products/natural-non-prescription/regulation/information-kit.html and https://www.cmaj.ca/content/189/25/E848", "notes": "", "urls": ["http://www.canada.ca/en/health-canada/services/drugs-health-products/natural-non-prescription/regulation/information-kit.html", "https://www.cmaj.ca/content/189/25/E848"]}, {"id": "16-006", "chapter_num": 16, "chapter_title": "Living with a chronic disease", "chapter_file": "16-living-with-chronic-disease.md", "number": 6, "title": "Keep one logbook for all your numbers", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "death", "evidence": "C", "grade": "C", "disputed": false, "cost": "Free. A notebook or a phone note, and a few minutes a day.", "plain": "One place — a notebook, a phone file — where you write down blood pressure, blood sugar, weight, and every dose you take. It catches slow drift that memory hides, and it hands your doctor real data instead of guesses.", "benefit_text": "No trial proves a logbook saves lives; this is the author's advice, graded accordingly. The logic: doctors adjust doses from trends, and trends only exist if someone writes the numbers down. Hypertension Canada's own home blood pressure log tells patients to bring the log and their medications to every appointment — the professionals want the numbers.", "sources": "https://hypertension.ca/wp-content/uploads/2017/11/HTC_BloodPressureLog_ENG_PREVIEW-1-Old2.pdf", "notes": "", "urls": ["https://hypertension.ca/wp-content/uploads/2017/11/HTC_BloodPressureLog_ENG_PREVIEW-1-Old2.pdf"]}, {"id": "17-001", "chapter_num": 17, "chapter_title": "Elderly parents at home", "chapter_file": "17-elderly-parents.md", "number": 1, "title": "Get the CPP/QPP timing right before your parents claim", "money": "0", "time": "mid", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; a few hours of research and one family conversation with the numbers in front of you.", "plain": "Claiming early shrinks the monthly cheque permanently, and waiting grows it. The decision cannot be undone, so make it with full information rather than at the Service Canada counter.", "benefit_text": "The 2026 maximum at age 65 is $1,507.65/month (January 2026 figure); starting at 60 cuts it by up to 36%, while waiting until 70 raises it by up to 42% — a lifetime difference worth tens of thousands of dollars.", "sources": "https://www.canada.ca/en/services/benefits/publicpensions/cpp/when-start.html https://www.canada.ca/en/services/benefits/publicpensions/cpp.html", "notes": "", "urls": ["https://www.canada.ca/en/services/benefits/publicpensions/cpp.html", "https://www.canada.ca/en/services/benefits/publicpensions/cpp/when-start.html"]}, {"id": "17-002", "chapter_num": 17, "chapter_title": "Elderly parents at home", "chapter_file": "17-elderly-parents.md", "number": 2, "title": "Check OAS and GIS entitlement every year", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "A", "grade": "A", "disputed": false, "cost": "No money; about an hour to read the annual notice and call Service Canada if something is missing.", "plain": "The basic pension is not always started automatically, and the income-tested top-up is missed by many eligible seniors. Check both every year, because entitlement changes with income.", "benefit_text": "OAS paid $751.97/month at ages 65–74 and $827.17 at 75+ in Q3 2026; the Guaranteed Income Supplement adds up to $1,123.17/month for a low-income single senior — over $13,000 a year that some eligible seniors never receive.", "sources": "https://www.canada.ca/content/dam/canada/employment-social-development/migration/documents/assets/portfolio/docs/en/statistics/quarterly_report/isp-card-jul-sep-2026-en.pdf", "notes": "", "urls": ["https://www.canada.ca/content/dam/canada/employment-social-development/migration/documents/assets/portfolio/docs/en/statistics/quarterly_report/isp-card-jul-sep-2026-en.pdf"]}, {"id": "17-003", "chapter_num": 17, "chapter_title": "Elderly parents at home", "chapter_file": "17-elderly-parents.md", "number": 3, "title": "Put powers of attorney in place while your parents are clearly capable", "money": "0", "time": "mid", "willpower": "some", "benefit": "mid", "dimension": "money", "evidence": "A", "grade": "A", "disputed": false, "cost": "No money for Ontario's free kit; a few hours plus one frank family conversation.", "plain": "One document covers money and property, another covers health and personal care. Without them, a court process decides who gets to speak for a parent who can no longer decide.", "benefit_text": "Avoids court-appointed guardianship proceedings that cost families thousands of dollars and months of delay.", "sources": "http://www.ontario.ca/page/make-power-attorney https://cdn-contenu.quebec.ca/cdn-contenu/curateur-public/pdf/form_broc_mandat_en.pdf", "notes": "Ontario: two documents — Property (18+) and Personal Care (16+) — signed with two witnesses present. Quebec: a mandat de protection only takes effect after court homologation, which requires medical and psychosocial assessments.", "urls": ["http://www.ontario.ca/page/make-power-attorney", "https://cdn-contenu.quebec.ca/cdn-contenu/curateur-public/pdf/form_broc_mandat_en.pdf"]}, {"id": "17-004", "chapter_num": 17, "chapter_title": "Elderly parents at home", "chapter_file": "17-elderly-parents.md", "number": 4, "title": "Give your parents a refusal script for the \"grandchild in trouble\" call", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; the Canadian Anti-Fraud Centre line at 1-888-495-8501 is free to call.", "plain": "The caller claims a grandchild is in trouble and needs cash immediately, and begs for secrecy. Real emergencies never demand gift cards, cash couriers, plus silence — hang up and call the grandchild directly.", "benefit_text": "One refused call can save the entire amount a scammer asked for; reports to the CAFC at 1-888-495-8501 help track the pattern.", "sources": "https://rcmp.ca/en/bc/hope/news/2026/05/4353598 https://www.canada.ca/en/national-seniors-council/programs/publications-reports/2019-what-we-heard-financial-crimes-harms.html", "notes": "", "urls": ["https://rcmp.ca/en/bc/hope/news/2026/05/4353598", "https://www.canada.ca/en/national-seniors-council/programs/publications-reports/2019-what-we-heard-financial-crimes-harms.html"]}, {"id": "17-005", "chapter_num": 17, "chapter_title": "Elderly parents at home", "chapter_file": "17-elderly-parents.md", "number": 5, "title": "Require two-person confirmation for any large or unusual payment", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money; a few minutes of friction per transaction.", "plain": "Agree in advance that no investment, donation, and supposedly urgent transfer above a set amount happens until a second family member confirms it on a separate call.", "benefit_text": "A second pair of eyes catches pressure tactics and impersonation that one person alone often misses.", "sources": "https://www.canada.ca/en/national-seniors-council/programs/publications-reports/2019-what-we-heard-financial-crimes-harms.html", "notes": "", "urls": ["https://www.canada.ca/en/national-seniors-council/programs/publications-reports/2019-what-we-heard-financial-crimes-harms.html"]}, {"id": "17-006", "chapter_num": 17, "chapter_title": "Elderly parents at home", "chapter_file": "17-elderly-parents.md", "number": 6, "title": "Treat \"pay first to unlock returns\" as fraud, not investing", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; the discipline to walk away from the pitch.", "plain": "Advance fees, crypto \"recovery\" agents, and promises of high returns all target seniors' savings. Once money is sent, it is almost never recovered — and paying more to \"recover\" earlier losses only deepens the hole.", "benefit_text": "Fraud over $5,000 carries up to 14 years' imprisonment under section 380 of the Criminal Code; reporting it protects the next target.", "sources": "https://criminalnotebook.ca/index.php?title=History_of_Fraud_Offences&mobileaction=toggle_view_desktop https://www.canada.ca/en/national-seniors-council/programs/publications-reports/2019-what-we-heard-financial-crimes-harms.html", "notes": "UNVERIFIED — the section 380 figures ($5,000 line, 14-year maximum) rest on a secondary legal site quoting the Code verbatim; no primary laws-lois URL was captured at write time. See docs/verification/17-elderly-parents.md.", "urls": ["https://criminalnotebook.ca/index.php?title=History_of_Fraud_Offences&mobileaction=toggle_view_desktop", "https://www.canada.ca/en/national-seniors-council/programs/publications-reports/2019-what-we-heard-financial-crimes-harms.html"]}, {"id": "17-007", "chapter_num": 17, "chapter_title": "Elderly parents at home", "chapter_file": "17-elderly-parents.md", "number": 7, "title": "Never sign home-equity or mortgage paperwork from a cold call", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money; the willingness to hang up and call back through a known number.", "plain": "Pressure to sign \"today only\" — for a reverse mortgage, a home-equity loan, a supposed government grant tied to the house — is a classic way to strip a senior's equity.", "benefit_text": "Keeps the home — usually the family's largest asset — out of contracts signed under pressure.", "sources": "https://www.canada.ca/en/national-seniors-council/programs/publications-reports/2019-what-we-heard-financial-crimes-harms.html", "notes": "", "urls": ["https://www.canada.ca/en/national-seniors-council/programs/publications-reports/2019-what-we-heard-financial-crimes-harms.html"]}, {"id": "17-008", "chapter_num": 17, "chapter_title": "Elderly parents at home", "chapter_file": "17-elderly-parents.md", "number": 8, "title": "Make a will; without one, the province decides", "money": "low", "time": "mid", "willpower": "some", "benefit": "low", "dimension": "money", "evidence": "A", "grade": "A", "disputed": false, "cost": "Low money for a simple will; a few hours to list assets and name an executor.", "plain": "Dying without a will means provincial default rules divide the estate — an unmarried partner may receive nothing, and administration costs more.", "benefit_text": "A valid will shortens estate administration and keeps assets out of default intestacy rules.", "sources": "https://www.ontario.ca/laws/statute/90s26/v8?search=wills+and+trusts", "notes": "Ontario: sign at the end of the will with two witnesses present together; a beneficiary or their spouse should not witness. Quebec wills follow the Civil Code (notarial or holograph forms) — confirm the current form with a notary.", "urls": ["https://www.ontario.ca/laws/statute/90s26/v8?search=wills+and+trusts"]}, {"id": "17-009", "chapter_num": 17, "chapter_title": "Elderly parents at home", "chapter_file": "17-elderly-parents.md", "number": 9, "title": "Fall-proof the home before the first fall", "money": "low", "time": "mid", "willpower": "no", "benefit": "low", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "Low money for grab bars, lighting, and removing trip hazards; a weekend of work.", "plain": "Falls are the leading cause of injury hospitalization for older adults, and roughly a quarter of seniors fall in any given year. Rails, lighting, and clear floors cut the odds.", "benefit_text": "About 20–30% of seniors fall each year (Public Health Agency of Canada); fewer falls means fewer hip fractures and hospital stays — the events that most often end independent living.", "sources": "https://www.canada.ca/en/public-health/services/health-promotion/aging-seniors/preventing-falls-injuries-older-adults.html", "notes": "", "urls": ["https://www.canada.ca/en/public-health/services/health-promotion/aging-seniors/preventing-falls-injuries-older-adults.html"]}, {"id": "17-010", "chapter_num": 17, "chapter_title": "Elderly parents at home", "chapter_file": "17-elderly-parents.md", "number": 10, "title": "Reposition a bed-bound parent every few hours", "money": "0", "time": "high", "willpower": "yes", "benefit": "low", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; significant daily time and effort from whoever provides care.", "plain": "Skin breaks down fast where bone presses against a mattress. Regular turning, plus keeping skin clean and dry, prevents wounds that are slow to heal and quick to infect.", "benefit_text": "The Registered Nurses' Association of Ontario recommends repositioning people at risk every two to four hours; preventing pressure injuries avoids infection and hospitalization.", "sources": "https://RNAO.ca/news/media-releases/updated-evidence-based-recommendations-for-managing-pressure-injuries", "notes": "Evidence note: RNAO clinical-guideline recommendations applied to home care.", "urls": ["https://RNAO.ca/news/media-releases/updated-evidence-based-recommendations-for-managing-pressure-injuries"]}, {"id": "17-011", "chapter_num": 17, "chapter_title": "Elderly parents at home", "chapter_file": "17-elderly-parents.md", "number": 11, "title": "Claim the Canada Caregiver Credit on your own return", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; a few extra lines on the tax return.", "plain": "If you support an infirm parent, the tax system offers a non-refundable credit — but only if you claim it. Many caregivers leave it on the table.", "benefit_text": "Up to $8,773 in claimable amount for 2026 (lines 30450/30425), worth about $1,228 off federal tax at the lowest bracket rate.", "sources": "https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/about-your-tax-return/tax-return/completing-a-tax-return/deductions-credits-expenses/canada-caregiver-amount.html", "notes": "", "urls": ["https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/about-your-tax-return/tax-return/completing-a-tax-return/deductions-credits-expenses/canada-caregiver-amount.html"]}, {"id": "17-012", "chapter_num": 17, "chapter_title": "Elderly parents at home", "chapter_file": "17-elderly-parents.md", "number": 12, "title": "Ontario: check GAINS. Quebec: check the home-support tax credit", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; GAINS needs no application, and the Quebec credit is claimed on the tax return.", "plain": "Ontario tops up low-income seniors automatically each month; Quebec refunds part of home-support service costs for seniors. Both are missed by people who never look.", "benefit_text": "GAINS paid up to $92/month for a single senior ($184 for a couple) in 2026–27, non-taxable; Quebec's 2026 credit is income-tested with thresholds of $72,465 and $117,395.", "sources": "http://www.ontario.ca/page/guaranteed-annual-income-system-payments-seniors https://www.revenuquebec.ca/documents/fr/publications/in/IN-311%282026-01%29.pdf", "notes": "", "urls": ["http://www.ontario.ca/page/guaranteed-annual-income-system-payments-seniors", "https://www.revenuquebec.ca/documents/fr/publications/in/IN-311%282026-01%29.pdf"]}, {"id": "18-001", "chapter_num": 18, "chapter_title": "Having kids: is it worth it", "chapter_file": "18-having-kids.md", "number": 1, "title": "File for the Canada Child Benefit from month one", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; enrolment is usually automatic with the birth registration, or one CRA application.", "plain": "The CCB is the largest single child benefit in the country and it is tax-free. It is income-tested, so apply even if you assume you earn too much — the phase-out starts higher than most people guess.", "benefit_text": "For July 2026–June 2027: up to $8,157 per year per child under six ($679.75/month) and $6,883 for ages six to seventeen; the full benefit goes to families under $38,237 net income.", "sources": "Richter D et al. (2019). Long-term effects of pregnancy and childbirth on sleep satisfaction and duration of first-time and experienced mothers and fathers. Sleep. <https://doi.org/10.1093/sleep/zsz015> (premise — new parents lose substantial sleep for years; the log-keeping itself is author advice, not a studied intervention)", "notes": "Quebec families also receive Allocation famille from Retraite Québec — up to $3,068 per child in 2026, plus a single-parent supplement: https://cdn-contenu.quebec.ca/cdn-contenu/adm/min/finances/publications-adm/parametres/AUTFR_RegimeImpot2026.pdf", "urls": ["https://cdn-contenu.quebec.ca/cdn-contenu/adm/min/finances/publications-adm/parametres/AUTFR_RegimeImpot2026.pdf", "https://doi.org/10.1093/sleep/zsz015"]}, {"id": "18-002", "chapter_num": 18, "chapter_title": "Having kids: is it worth it", "chapter_file": "18-having-kids.md", "number": 2, "title": "Outside Quebec: use EI maternity and parental benefits — insurance you already paid for", "money": "0", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money to claim; 600 insurable hours in the previous 52 weeks to qualify.", "plain": "Maternity benefits cover the birth parent around the birth; parental benefits can be shared between parents. File as soon as you stop working — late applications can cost you weeks.", "benefit_text": "55% of insurable earnings up to $729/week in 2026: 15 weeks maternity, plus 35 weeks standard parental (40 shareable between parents) or 61 weeks extended at $437/week (69 shareable).", "sources": "EI maternity and parental benefits — how much you could receive (2026: 55% to $729/week standard; 33% to $437/week extended). https://www.canada.ca/en/services/benefits/ei/ei-maternity-parental/benefit-amount.html ; week counts verified 2026-10-01 on ESDC's Digest of Benefit Entitlement Principles (standard parental max 35 weeks at 55%, extended max 61 weeks at 33%, shareable to 40/69 weeks): https://www.canada.ca/en/employment-social-development/programs/ei/ei-list/reports/digest/chapter-13/parental-benefits-payments.html", "notes": "Quebec residents are covered by QPIP instead of EI for parental benefits — never both. See item 3.", "urls": ["https://www.canada.ca/en/employment-social-development/programs/ei/ei-list/reports/digest/chapter-13/parental-benefits-payments.html", "https://www.canada.ca/en/services/benefits/ei/ei-maternity-parental/benefit-amount.html"]}, {"id": "18-003", "chapter_num": 18, "chapter_title": "Having kids: is it worth it", "chapter_file": "18-having-kids.md", "number": 3, "title": "In Quebec: QPIP replaces EI — learn its two plans before the birth", "money": "0", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money to claim; premiums already come off paycheques, and the plan choice binds both parents once the first one files.", "plain": "Quebec runs its own parental insurance with no one-week waiting period. The basic plan pays longer at lower rates; the special plan pays shorter at higher rates. Choose before the baby arrives, because the first filer's choice is final.", "benefit_text": "Basic plan: 18 weeks maternity at 70%, five weeks paternity at 70%, 32 weeks shareable parental (first seven at 70%, the rest at 55%), plus four extra weeks at 55% once each parent has taken eight shareable weeks. Special plan: 15/3/25 weeks at 75%, plus three extra weeks at 75% once each parent has taken six.", "sources": "QPIP general portal — https://www.rqap.gouv.qc.ca/en (plan figures — basic 18/5/32, special 15/3/25 — verified on the official QPIP choice-of-plan benefits table)", "notes": "EI parental benefits do not apply in Quebec — never claim both. UNVERIFIED — the 2026 maximum insurable earnings ($103,000) is from secondary sources; confirm the current figure on the QPIP site before estimating payments. See docs/verification/18-having-kids.md.", "urls": ["https://www.rqap.gouv.qc.ca/en"]}, {"id": "18-004", "chapter_num": 18, "chapter_title": "Having kids: is it worth it", "chapter_file": "18-having-kids.md", "number": 4, "title": "In Ontario: get on the $10-a-day path before the baby arrives", "money": "low", "time": "mid", "willpower": "some", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Licensed child-care fees while you wait for a space; real time spent on waitlists.", "plain": "Ontario's agreement with Ottawa is pushing licensed fees for children under six toward an average of ten dollars a day. Spaces are the bottleneck, so join waitlists early.", "benefit_text": "Fees already cut roughly in half since 2022, saving families up to $8,500 per child per year; the agreement targets an average of $10/day by the end of fiscal 2025–26.", "sources": "https://www.canada.ca/en/early-learning-child-care-agreement/agreements-provinces-territories/ontario-canada-wide-2021.html", "notes": "Quebec runs its own reduced-fee child-care system outside this agreement. EI/QPIP benefits (items 2–3) cover the leave period; child-care costs start after.", "urls": ["https://www.canada.ca/en/early-learning-child-care-agreement/agreements-provinces-territories/ontario-canada-wide-2021.html"]}, {"id": "18-005", "chapter_num": 18, "chapter_title": "Having kids: is it worth it", "chapter_file": "18-having-kids.md", "number": 5, "title": "Open an RESP and collect the federal grant", "money": "low", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Contributions are your own savings, not a cost — the grant only flows on the first $2,500 contributed per year.", "plain": "The government adds twenty percent to your education savings automatically once the account exists. No RESP means no grant, and the years do not come back.", "benefit_text": "Canada Education Savings Grant: 20% on the first $2,500 contributed per year ($500/year), up to $1,000 in a catch-up year, $7,200 lifetime per child.", "sources": "https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/registered-education-savings-plans-resps/canada-education-savings-programs-cesp/canada-education-savings-grant-cesg.html", "notes": "", "urls": ["https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/registered-education-savings-plans-resps/canada-education-savings-programs-cesp/canada-education-savings-grant-cesg.html"]}, {"id": "18-006", "chapter_num": 18, "chapter_title": "Having kids: is it worth it", "chapter_file": "18-having-kids.md", "number": 6, "title": "Know your job-protected leave: Ontario and Quebec differ", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; know your dates before you notify your employer.", "plain": "Benefits pay you; employment standards protect your job. The two systems run on different clocks, so check the one for your province — and remember the money comes from EI outside Quebec and QPIP inside it, never both.", "benefit_text": "Ontario: up to 17 weeks pregnancy leave plus 61 weeks parental (63 without pregnancy leave), after 13 weeks with the employer. Quebec: 18 weeks maternity, five weeks paternity, and up to 65 weeks parental under provincial labour standards.", "sources": "https://pelslaw.ca/maternity-and-parental-leave/ https://www.monkhouselaw.com/ontario-parental-leave/", "notes": "UNVERIFIED — the week figures rest on secondary legal sites, not the primary statute pages; confirm on ontario.ca and cnesst.gouv.qc.ca. See docs/verification/18-having-kids.md. EI/QPIP warning: leave is job protection, not money — the money comes from EI (item 2) or QPIP (item 3), never both.", "urls": ["https://pelslaw.ca/maternity-and-parental-leave/", "https://www.monkhouselaw.com/ontario-parental-leave/"]}, {"id": "18-007", "chapter_num": 18, "chapter_title": "Having kids: is it worth it", "chapter_file": "18-having-kids.md", "number": 7, "title": "Price the first three years by care arrangement before deciding", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; an evening with a spreadsheet and your actual local numbers.", "plain": "Centre care, home daycare, a nanny, a parent staying home — all four carry wildly different price tags. Write each down before the baby comes, because the ranking surprises most families.", "benefit_text": "The cheapest arrangement can differ by tens of thousands over three years — but only a written comparison shows it for your family.", "sources": "https://www.canada.ca/en/early-learning-child-care-agreement/agreements-provinces-territories/ontario-canada-wide-2021.html", "notes": "", "urls": ["https://www.canada.ca/en/early-learning-child-care-agreement/agreements-provinces-territories/ontario-canada-wide-2021.html"]}, {"id": "18-008", "chapter_num": 18, "chapter_title": "Having kids: is it worth it", "chapter_file": "18-having-kids.md", "number": 8, "title": "Run a night-shift ledger for one month before deciding about another child", "money": "0", "time": "low", "willpower": "some", "benefit": "low", "dimension": "time", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money; a notebook by the bed and the honesty to log every waking.", "plain": "Memory lies about how bad the nights were. A written log of who got up, when, and for how long tells you what another newborn would actually cost in sleep.", "benefit_text": "Turns vague dread into a measured number of lost hours per week — the input the decision actually needs.", "sources": "https://www.canada.ca/en/revenue-agency/services/child-family-benefits/canada-child-benefit/how-much.html", "notes": "", "urls": ["https://www.canada.ca/en/revenue-agency/services/child-family-benefits/canada-child-benefit/how-much.html"]}, {"id": "18-009", "chapter_num": 18, "chapter_title": "Having kids: is it worth it", "chapter_file": "18-having-kids.md", "number": 9, "title": "Write down why you want kids — separately from money", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "time", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money; one honest conversation, ideally written down.", "plain": "Old-age support, carrying on the family line, wanting the experience — different goals with different price tags. Public pensions do not depend on having children.", "benefit_text": "Separating motives from finances stops you from paying a child's price for a pension's goal.", "sources": "https://www.canada.ca/content/dam/canada/employment-social-development/migration/documents/assets/portfolio/docs/en/statistics/quarterly_report/isp-card-jul-sep-2026-en.pdf", "notes": "", "urls": ["https://www.canada.ca/content/dam/canada/employment-social-development/migration/documents/assets/portfolio/docs/en/statistics/quarterly_report/isp-card-jul-sep-2026-en.pdf"]}, {"id": "19-001", "chapter_num": 19, "chapter_title": "Jobs, dismissal, and work injuries", "chapter_file": "19-jobs-dismissal-injuries.md", "number": 1, "title": "Ontario overtime: 1.5x after 44 hours a week", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Ontario. No money. Keep copies of your schedules and pay stubs; the hard part is remembering to save them each month.", "plain": "In Ontario, every hour past 44 in a week must be paid at one and one-half times your regular rate. Managers and supervisors are exempt.", "benefit_text": "ESA s.22(1): \"an employer shall pay an employee overtime pay of at least one and one-half times his or her regular rate for each hour of work in excess of 44 hours in each week\" (2026). No daily overtime threshold in Ontario: the trigger is weekly. A worker doing 5 overtime hours a week at $25/hr earns about $3,250 a year in premiums alone (2026 dollars).", "sources": "http://www.ontario.ca/document/your-guide-employment-standards-act-0/overtime-pay ; https://www.ontario.ca/laws/statute/00e41/v24", "notes": "Ontario only. Some occupations are exempt; check the ESA guide for your job. No statutory probation period exists in Ontario: overtime applies from the first hour worked. Benefit graded high: premiums compound past $50,000 over a working life.", "urls": ["http://www.ontario.ca/document/your-guide-employment-standards-act-0/overtime-pay", "https://www.ontario.ca/laws/statute/00e41/v24"]}, {"id": "19-002", "chapter_num": 19, "chapter_title": "Jobs, dismissal, and work injuries", "chapter_file": "19-jobs-dismissal-injuries.md", "number": 2, "title": "Quebec overtime: +50% after 40 hours", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Quebec. No money. Same habit: save schedules and pay stubs.", "plain": "In Quebec, the regular work week is 40 hours. Every hour past 40 must be paid at your regular rate plus 50%. The premium is calculated on your regular wage.", "benefit_text": "LNT s.52 sets the regular workweek at 40 hours; s.55 adds a 50% premium for overtime hours (2026). Quebec's general minimum is $16.60/hr since 2026-05-01; CNESST's worked overtime example still prices at the previous $16.10/hr rate. A worker doing 5 overtime hours a week at $20/hr earns about $2,600 a year in premiums (2026 dollars).", "sources": "https://www.cnesst.gouv.qc.ca/en/working-conditions/wage-and-pay/wages/overtime ; https://www.legisquebec.gouv.qc.ca/fr/document/lc/n-1.1/20230608?langCont=en", "notes": "Quebec only. Minimum-wage figure ($16.60/hr from 2026-05-01) corroborated via published rate tables (wageindicator.org, workforce.com); CNESST's worked overtime example still uses the previous $16.10/hr rate. Benefit graded high: premiums compound past $50,000 over a working life.", "urls": ["https://www.cnesst.gouv.qc.ca/en/working-conditions/wage-and-pay/wages/overtime", "https://www.legisquebec.gouv.qc.ca/fr/document/lc/n-1.1/20230608?langCont=en"]}, {"id": "19-003", "chapter_num": 19, "chapter_title": "Jobs, dismissal, and work injuries", "chapter_file": "19-jobs-dismissal-injuries.md", "number": 3, "title": "Ontario workplace injury: WSIB and the 3-business-day rule", "money": "0", "time": "mid", "willpower": "some", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Ontario. No money. The claim takes hours of forms and follow-up; the hard part is reporting promptly and keeping medical records.", "plain": "In Ontario, a workplace injury goes to the WSIB, not to your employer's goodwill. Your employer must file a Form 7 within three business days. Benefits replace 85% of net average earnings while you cannot work.", "benefit_text": "WSIB (2026): loss-of-earnings (LOE) benefits at 85% of net average earnings. Employer must report within 3 business days (Form 7); late filing draws a $250 penalty, more than 30 calendar days $1,000; offence fines reach $25,000 for individuals and $500,000 for corporations — fine figures UNVERIFIED in this edition (not confirmed on the cited WSIB pages; see docs/verification/spot-read.md). A year of LOE at 85% of a $60,000 net salary is about $51,000 (2026 dollars).", "sources": "https://www.wsib.ca/en/administrative-practice-document-loss-earnings-loe-benefit-reviews ; https://www.WSIB.ca/en/employers-report-injury-disease-form-7-reference-guide-businesses ; https://www.wsib.ca/en/operational-policy-manual/employers-initial-accident-reporting-obligations", "notes": "Ontario only. Business days, not calendar days, for the Form 7 deadline. Benefit graded high: a single year of LOE at a $60,000 net salary already passes $50,000.", "urls": ["https://www.WSIB.ca/en/employers-report-injury-disease-form-7-reference-guide-businesses", "https://www.wsib.ca/en/administrative-practice-document-loss-earnings-loe-benefit-reviews", "https://www.wsib.ca/en/operational-policy-manual/employers-initial-accident-reporting-obligations"]}, {"id": "19-004", "chapter_num": 19, "chapter_title": "Jobs, dismissal, and work injuries", "chapter_file": "19-jobs-dismissal-injuries.md", "number": 4, "title": "Quebec workplace injury: CNESST and the 6-month claim window", "money": "0", "time": "mid", "willpower": "some", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Quebec. No money. File the worker's claim form promptly and keep every medical receipt.", "plain": "In Quebec, a workplace injury goes to the CNESST. You have six months to file the worker's claim form, called the Réclamation du travailleur. File it online. Filing by mail also works. Your employer may not punish you for being absent, and may not punish you for filing.", "benefit_text": "CNESST (2026): 6 months to file the Réclamation du travailleur from the accident. Income replacement after the first day is set by the Act respecting industrial accidents and occupational diseases, arts. 45–46 — the exact rate and who pays the first 14 days are UNVERIFIED at write time (labour.md #6). Retaliation for filing is prohibited; complaints about punishment go to CNESST within 30 days.", "sources": "https://www.ccq.org/en/annexes/lr/reclamation-cnesst", "notes": "Quebec only. The 6-month deadline and the Réclamation du travailleur form are corroborated by construction-sector guidance describing the general CNESST process (ccq.org); a CNESST-published English page for the general claim process was not captured at write time. Income-replacement rate UNVERIFIED (labour.md #6). CNESST: 1-844-838-0808 (verified 2026-09-30 on cnesst.gouv.qc.ca; write-time URL not captured). Benefit graded high: months of income replacement clear $50,000 cumulatively.", "urls": ["https://www.ccq.org/en/annexes/lr/reclamation-cnesst"]}, {"id": "19-005", "chapter_num": 19, "chapter_title": "Jobs, dismissal, and work injuries", "chapter_file": "19-jobs-dismissal-injuries.md", "number": 5, "title": "Reasonable notice: the ESA floor is not the ceiling", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money for a first consultation, often free. Ten minutes to learn the four factors before you sign a release.", "plain": "The ESA minimums are a floor, not a ceiling. Courts award reasonable notice based on four factors: length of service, age, character of employment, and availability of similar work. Awards often run many months. Never sign a release on the spot; get advice first.", "benefit_text": "Bardal v. Globe & Mail (1960): reasonable notice is set case by case having regard to the character of the employment, the length of service, the age of the employee, and the availability of similar employment given experience, training and qualifications. ESA s.57 and s.64 minimums do not cap common-law notice. A 10-year employee awarded 12 months at a $70,000 salary receives about $70,000 (2026 dollars).", "sources": "https://www.ontario.ca/laws/statute/00e41/v24 ; https://emond.ca/Emond/media/Sample-chapters/elp08ch08_2nd_1.pdf", "notes": "Applies in both provinces; Quebec civil law reaches similar results through art.2088 C.C.Q. reasonable notice — UNVERIFIED at write time (no primary source captured). Enforcement needs a lawsuit or a lawyer's demand letter; the item here is the knowledge plus a consultation, which is why money cost is 0. Benefit graded high: 12 months at a $70,000 salary clears $50,000.", "urls": ["https://emond.ca/Emond/media/Sample-chapters/elp08ch08_2nd_1.pdf", "https://www.ontario.ca/laws/statute/00e41/v24"]}, {"id": "19-006", "chapter_num": 19, "chapter_title": "Jobs, dismissal, and work injuries", "chapter_file": "19-jobs-dismissal-injuries.md", "number": 6, "title": "Federal unjust dismissal: 90 days to complain", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Federal jurisdiction only. No money to file. The deadline is short: 90 days.", "plain": "In federally regulated workplaces, non-union employees with twelve months of continuous service can challenge a dismissal as unjust. Complaints go to the Labour Program within 90 days. Remedies can include reinstatement with back pay.", "benefit_text": "Canada Labour Code s.240 (2026): 12 consecutive months of continuous employment, non-unionized employee, written complaint within 90 days of dismissal. Adjudicators can order reinstatement and compensation for lost wages. A year of back pay at a $60,000 salary is $60,000 (2026 dollars).", "sources": "https://laws-lois.justice.gc.ca/eng/acts/l-2/section-240-20240620.html", "notes": "Federal jurisdiction only — about 6% of Canadian employees (banks, telecoms, interprovincial and international transport, federal Crown corporations). Provincial employees use provincial complaints instead: Ontario via the Ministry; Quebec art.124 within 45 days for employees with 2 years of service. Benefit graded high: a year of back pay at a $60,000 salary clears $50,000.", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/l-2/section-240-20240620.html"]}, {"id": "19-007", "chapter_num": 19, "chapter_title": "Jobs, dismissal, and work injuries", "chapter_file": "19-jobs-dismissal-injuries.md", "number": 7, "title": "Know the wage floor before you accept a job", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money. One look at the current rate before you accept a job.", "plain": "The wage floor moves. Ontario's general rate is $17.95 an hour starting 2026-10-01. Quebec's general rate is $16.60 an hour in 2026. The federal rate for federally regulated workplaces is $18.15 an hour in 2026. Lower rates exist for students, homeworkers, and tipped staff.", "benefit_text": "Ontario $17.95/hr general rate effective 2026-10-01; student $16.90/hr; homeworker $19.70/hr (2026). Quebec $16.60/hr general rate (2026). Federal $18.15/hr effective 2026-04-01 (2026). Two years of back pay at a $2/hr underpayment, full time, is about $8,320 (2026 dollars).", "sources": "http://www.ontario.ca/document/your-guide-employment-standards-act-0/minimum-wage ; https://www.cnesst.gouv.qc.ca/en/working-conditions/wage-and-pay/wages/overtime ; https://www.canada.ca/en/employment-social-development/corporate/portfolio/labour/bulletin/march-2026.html", "notes": "Quebec tipped-employee rate excluded: $13.20 and $13.30 versions conflict with no primary source — UNVERIFIED (labour.md #2), left out rather than guessed. ESA and LNT rights apply whether or not you signed a written contract. Benefit graded mid: two years of back pay at a $2/hr underpayment sits inside $5,000–$50,000.", "urls": ["http://www.ontario.ca/document/your-guide-employment-standards-act-0/minimum-wage", "https://www.canada.ca/en/employment-social-development/corporate/portfolio/labour/bulletin/march-2026.html", "https://www.cnesst.gouv.qc.ca/en/working-conditions/wage-and-pay/wages/overtime"]}, {"id": "19-008", "chapter_num": 19, "chapter_title": "Jobs, dismissal, and work injuries", "chapter_file": "19-jobs-dismissal-injuries.md", "number": 8, "title": "EI: 55% of pay, up to $729 a week", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money. Apply online as soon as you stop working; delay costs weeks of benefits.", "plain": "Employment Insurance replaces 55% of average insurable earnings, up to $729 a week in 2026, for 14 to 45 weeks depending on hours worked and the regional unemployment rate. You need 420 to 700 insured hours in the last 52 weeks. Your employer must issue the Record of Employment within five calendar days.", "benefit_text": "EI (2026): 55% of average insurable earnings; maximum insurable earnings $68,900; maximum $729/week; 14 to 45 weeks; 420 to 700 insurable hours in the qualifying 52-week period; Record of Employment due within 5 calendar days of interruption of earnings. A full 45-week claim at the maximum is about $32,805 (2026 dollars).", "sources": "https://www.canada.ca/en/services/benefits/ei/ei-regular-benefit/benefit-amount.html ; https://www.canada.ca/en/employment-social-development/programs/ei/ei-list/ei-employers/premium-reduction-program/2026-maximum-insurable-earnings.html ; https://www.canada.ca/en/services/benefits/ei/ei-regular-benefit/eligibility.html", "notes": "Quitting without just cause or dismissal for misconduct disqualifies you — see the resignation item. Benefit graded mid: a maximum single claim is about $32,805, inside $5,000–$50,000. EI: 1-800-206-7218.", "urls": ["https://www.canada.ca/en/employment-social-development/programs/ei/ei-list/ei-employers/premium-reduction-program/2026-maximum-insurable-earnings.html", "https://www.canada.ca/en/services/benefits/ei/ei-regular-benefit/benefit-amount.html", "https://www.canada.ca/en/services/benefits/ei/ei-regular-benefit/eligibility.html"]}, {"id": "19-009", "chapter_num": 19, "chapter_title": "Jobs, dismissal, and work injuries", "chapter_file": "19-jobs-dismissal-injuries.md", "number": 9, "title": "Parental benefits: EI outside Quebec, QPIP inside", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money. The trap is applying to the wrong plan, which delays payment by weeks.", "plain": "Job protection during parental leave is unpaid; the money comes from a separate benefit. Outside Quebec, EI maternity and parental benefits pay 55% up to $729 a week in 2026, with an extended option at a lower weekly maximum of $437. In Quebec, parental benefits come from the QPIP instead, with basic and special plans paying by the week.", "benefit_text": "EI maternity/parental (2026): standard rate 55% to a $729/week maximum; extended parental option to a $437/week maximum. QPIP basic plan (2026): maternity 18 weeks at 70%, paternity 5 weeks at 70%, parental 32 weeks (7 at 70% plus 25 at 55%) with 4 additional weeks at 55%; special plan: 15 weeks at 75%, 3 weeks at 75%, 25 weeks at 75% with 3 additional weeks at 75%. QPIP maximum insurable earnings for 2026 is UNVERIFIED (labour.md #8).", "sources": "https://www.canada.ca/en/services/benefits/ei/ei-maternity-parental/benefit-amount.html ; https://www.rqap-lois.gouv.qc.ca/en/wage-earners-who-are-also-self-employed/benefits-surrogacy-project", "notes": "Quebec residents claim QPIP, not EI, for maternity, paternity and parental benefits — the statutory mutual-exclusion text was not captured on a primary page at write time (UNVERIFIED). Applying to EI while living in Quebec delays payment. Benefit graded mid: a full parental claim approaches $30,000, inside $5,000–$50,000.", "urls": ["https://www.canada.ca/en/services/benefits/ei/ei-maternity-parental/benefit-amount.html", "https://www.rqap-lois.gouv.qc.ca/en/wage-earners-who-are-also-self-employed/benefits-surrogacy-project"]}, {"id": "19-010", "chapter_num": 19, "chapter_title": "Jobs, dismissal, and work injuries", "chapter_file": "19-jobs-dismissal-injuries.md", "number": 10, "title": "Ontario termination notice: the s.57 scale", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Ontario. No money. Ten minutes with a calculator.", "plain": "In Ontario, after three months with an employer, dismissal without cause comes with paid notice: 1 week for under a year of service, 2 weeks for 1 to 3 years, then an extra week per year up to 8 weeks. The employer can pay you instead of having you work the notice.", "benefit_text": "ESA s.57 (2026): under 1 year 1 week; 1–3 years 2 weeks; 3–4 years 3 weeks; 4–5 years 4 weeks; 5–6 years 5 weeks; 6–7 years 6 weeks; 7–8 years 7 weeks; 8 years and over 8 weeks. Applies only after 3 months of employment. For a $60,000 salary, 8 weeks is about $9,230 (2026 dollars).", "sources": "https://www.ontario.ca/laws/statute/00e41/v24 ; http://www.ontario.ca/document/employment-standard-act-policy-and-interpretation-manual/part-xv-termination-and-severance-employment", "notes": "Ontario only. This is the statutory floor. Courts can award much longer reasonable notice at common law — see the reasonable-notice item. No statutory probation: the 3-month line only switches notice on; minimum wage and overtime apply from day one.", "urls": ["http://www.ontario.ca/document/employment-standard-act-policy-and-interpretation-manual/part-xv-termination-and-severance-employment", "https://www.ontario.ca/laws/statute/00e41/v24"]}, {"id": "19-011", "chapter_num": 19, "chapter_title": "Jobs, dismissal, and work injuries", "chapter_file": "19-jobs-dismissal-injuries.md", "number": 11, "title": "Quebec termination notice: the art.82 scale", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Quebec. No money. Same ten-minute calculation.", "plain": "In Quebec, dismissal without cause also comes with notice: 1 week for under a year of service, 2 weeks for 1 to 5 years, 4 weeks for 5 to 10 years, 8 weeks past 10 years. The employer may pay the wages instead of giving notice.", "benefit_text": "LNT art.82 (2026): under 1 year 1 week; 1–5 years 2 weeks; 5–10 years 4 weeks; 10 years and over 8 weeks. Art.82.1: no notice for under 3 months of service, fixed-term expiry, serious fault, or superior force. Art.83: indemnity in lieu equals regular wages excluding overtime, paid at termination. For a $60,000 salary, 8 weeks is about $9,230 (2026 dollars).", "sources": "https://www.legisquebec.gouv.qc.ca/fr/document/lc/n-1.1/20230608?langCont=en ; https://www.cnesst.gouv.qc.ca/en/node/1147646/interpretation-guide/act-respecting-labour-standards/chapter-iv-larbour-standards-section-391-97/division-vi-notice-termination-employment-or/section-83", "notes": "Quebec only. For employees with 2 years of continuous service, Quebec also allows an unjust-dismissal complaint to CNESST within 45 days (LNT art.124, verified on legisquebec); the exact remedies are UNVERIFIED at write time (labour.md #13).", "urls": ["https://www.cnesst.gouv.qc.ca/en/node/1147646/interpretation-guide/act-respecting-labour-standards/chapter-iv-larbour-standards-section-391-97/division-vi-notice-termination-employment-or/section-83", "https://www.legisquebec.gouv.qc.ca/fr/document/lc/n-1.1/20230608?langCont=en"]}, {"id": "19-012", "chapter_num": 19, "chapter_title": "Jobs, dismissal, and work injuries", "chapter_file": "19-jobs-dismissal-injuries.md", "number": 12, "title": "Ontario severance: five years unlocks a second cheque", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Ontario. No money. Check two gates before you claim.", "plain": "In Ontario, five years of service can unlock severance on top of notice: one week of pay per year of service, up to 26 weeks. Two gates must both be open. Gate one: five years with the employer. Gate two: the employer's global payroll reaches $2.5 million. Mass layoffs of 50 people in six months open gate two another way.", "benefit_text": "ESA s.64 (2026): 1 week of regular wages per year of service, maximum 26 weeks. Gate one: 5 or more years of employment. Gate two: employer global payroll of $2.5 million or more, alternatively 50 or more employees severed within 6 months. For a $60,000 salary with 20 years of service, 20 weeks is about $23,080 (2026 dollars).", "sources": "https://www.ontario.ca/laws/statute/00e41/v24 ; http://www.ontario.ca/document/your-guide-employment-standards-act-0/young-workers-rights", "notes": "Ontario only. Quebec has no statutory severance: the art.82 notice is the whole statutory package there. Severance is separate from termination notice and separate from common-law reasonable notice.", "urls": ["http://www.ontario.ca/document/your-guide-employment-standards-act-0/young-workers-rights", "https://www.ontario.ca/laws/statute/00e41/v24"]}, {"id": "19-013", "chapter_num": 19, "chapter_title": "Jobs, dismissal, and work injuries", "chapter_file": "19-jobs-dismissal-injuries.md", "number": 13, "title": "Do not quit on the spot when you are pushed out", "money": "0", "time": "low", "willpower": "yes", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money. The hard part is resisting pressure to sign on the spot.", "plain": "Quitting voluntarily without just cause usually kills both severance and EI. Dismissal for misconduct does the same to EI. If you are being pushed out, do not sign a resignation letter the same day. Sleep on it and get advice.", "benefit_text": "EI eligibility (2026): no regular benefits if you \"voluntarily left your job without just cause\" or \"were dismissed for misconduct\". Protecting a potential $32,805 maximum claim is worth a day of patience (2026 dollars).", "sources": "https://www.canada.ca/en/services/benefits/ei/ei-regular-benefit/eligibility.html", "notes": "Constructive dismissal — a forced \"voluntary\" resignation after demotion or pay cuts — can count as just cause; that argument needs a lawyer. Benefit graded mid: it protects the EI claim in the EI item, up to about $32,805.", "urls": ["https://www.canada.ca/en/services/benefits/ei/ei-regular-benefit/eligibility.html"]}, {"id": "19-014", "chapter_num": 19, "chapter_title": "Jobs, dismissal, and work injuries", "chapter_file": "19-jobs-dismissal-injuries.md", "number": 14, "title": "Non-compete: banned in Ontario, possible in Quebec", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money. Read the clause before you sign; it governs where you can work next.", "plain": "Ontario and Quebec point opposite ways. In Ontario, non-compete clauses signed after 2021-10-25 are banned, with narrow exceptions for business sales and executives. In Quebec, a non-compete can bind you if it is in writing and limited in time, place, and type of work to the employer's legitimate interests.", "benefit_text": "Ontario ESA s.67.2(1) (2026): non-compete agreements signed after 2021-10-25 are prohibited; exceptions for business sales and executive employees. Quebec CCQ art.2089: \"Toute stipulation de non-concurrence doit, pour être valable, être stipulée par écrit en termes exprès, et être limitée quant au temps, au lieu et au type d'emploi, aux intérêts légitimes de l'employeur\"; the burden of proof lies on the employer. (2026)", "sources": "https://www.ontario.ca/laws/statute/00e41/v24 ; https://www.publicationsduquebec.gouv.qc.ca/index.php?eID=dumpFile&t=f&f=174508&token=081597f79476acc94a1c407db47a4234a27f0a4c", "notes": "Read non-solicitation clauses separately: Ontario's ban covers non-competes, not non-solicits. Benefit graded mid: a blocked job move can cost months of income, inside $5,000–$50,000.", "urls": ["https://www.ontario.ca/laws/statute/00e41/v24", "https://www.publicationsduquebec.gouv.qc.ca/index.php?eID=dumpFile&t=f&f=174508&token=081597f79476acc94a1c407db47a4234a27f0a4c"]}, {"id": "19-015", "chapter_num": 19, "chapter_title": "Jobs, dismissal, and work injuries", "chapter_file": "19-jobs-dismissal-injuries.md", "number": 15, "title": "Unpaid wages: WEPP for bankrupt employers, ministries otherwise", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money. File within the deadlines; late claims die.", "plain": "If your employer goes bankrupt owing you wages, the federal Wage Earner Protection Program pays up to $9,275 in 2026. You must have lost the job, be owed wages earned in the six months before insolvency, and file a proof of claim with the trustee. For ordinary unpaid wages, Ontario takes claims through the Ministry of Labour within two years. In Quebec, wage complaints go to the CNESST.", "benefit_text": "WEPP (2026): one-time payment up to 7 times the maximum weekly insurable earnings — $9,275 for 2026. Eligibility: job lost, wages owed by an insolvent employer, wages earned within the 6 months before insolvency; file a proof of claim with the trustee or receiver, then apply through Service Canada. Ontario: ESA claims to the Ministry of Labour within 2 years of the incident. Quebec: CNESST handles wage complaints; unjust-dismissal complaints within 45 days (LNT art.124).", "sources": "http://canada.ca/en/employment-social-development/services/wage-earner-protection/employee/benefit-amount.html ; https://www.canada.ca/en/employment-social-development/corporate/portfolio/labour/programs/labour-standards/reports/wage-protection.html ; http://www.ontario.ca/document/your-guide-employment-standards-act-0/young-workers-rights", "notes": "The Ontario 2-year claim window and the Ministry path are confirmed on ontario.ca (young workers' guide). Quebec CNESST wage-complaint specifics and TAT remedies: partially UNVERIFIED (labour.md #13) — the art.124 45-day deadline is verified on legisquebec. Benefit graded mid: $9,275 sits inside $5,000–$50,000.", "urls": ["http://canada.ca/en/employment-social-development/services/wage-earner-protection/employee/benefit-amount.html", "http://www.ontario.ca/document/your-guide-employment-standards-act-0/young-workers-rights", "https://www.canada.ca/en/employment-social-development/corporate/portfolio/labour/programs/labour-standards/reports/wage-protection.html"]}, {"id": "19-016", "chapter_num": 19, "chapter_title": "Jobs, dismissal, and work injuries", "chapter_file": "19-jobs-dismissal-injuries.md", "number": 16, "title": "Vacation and public holidays", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money. Know the rate before you trade vacation for cash.", "plain": "Ontario gives two weeks of vacation below five years of service and three weeks at five years and above, paid at 4% and 6% of wages. Quebec gives two weeks after one year and three weeks after three years. Ontario has nine public holidays; Quebec has eight. Unused vacation is paid out when the job ends.", "benefit_text": "Ontario (2026): 2 weeks vacation under 5 years of service, 3 weeks at 5 years and over; vacation pay 4% and 6% of gross wages respectively; 9 public holidays. Quebec (2026): 2 weeks after 1 year, 3 weeks after 3 years; 8 statutory holidays — the art.60 holiday list is UNVERIFIED at write time (labour.md #3). Vacation not taken is paid out on termination in both provinces.", "sources": "https://www.ontario.ca/laws/statute/00e41/v24 ; https://www.legisquebec.gouv.qc.ca/fr/document/lc/n-1.1/20230608?langCont=en", "notes": "Benefit graded low: a week of vacation pay is under $5,000 for most earners.", "urls": ["https://www.legisquebec.gouv.qc.ca/fr/document/lc/n-1.1/20230608?langCont=en", "https://www.ontario.ca/laws/statute/00e41/v24"]}, {"id": "19-017", "chapter_num": 19, "chapter_title": "Jobs, dismissal, and work injuries", "chapter_file": "19-jobs-dismissal-injuries.md", "number": 17, "title": "Sick leave: three different regimes, do not mix them", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money. Know which regime covers you before you need a day off.", "plain": "Sick-day rules depend on jurisdiction. Federally regulated employees accrue up to ten paid medical-leave days a year. Ontario gives a few unpaid sick days a year. Quebec gives mostly unpaid leave with two paid days. Check which regime covers you before you need a day off.", "benefit_text": "Federal (2026): up to 10 days of medical leave with pay per year (3 days after 30 days of continuous employment, then 1 more per month); in force 2022-12-01. Ontario: 3 unpaid sick days a year (ESA s.50) — UNVERIFIED at write time (labour.md #4). Quebec: 26 weeks of unpaid sick leave plus 2 paid days after 3 months of service (LNT art.79.1) — UNVERIFIED at write time (labour.md #4); Quebec birth leave 5 days with the first 2 paid (LNT art.81.1) — UNVERIFIED (labour.md #4).", "sources": "https://www.canada.ca/en/employment-social-development/programs/laws-regulations/labour/interpretations-policies/medical-leave-pay.html ; https://www.canada.ca/en/services/jobs/workplace/federal-labour-standards/leaves.html", "notes": "Do not merge the three regimes. Federal figures verified on canada.ca (ESDC IPG-118). Ontario and Quebec figures are secondary-sourced only — UNVERIFIED (labour.md #4). Benefit graded low: a few days of pay sits under $5,000.", "urls": ["https://www.canada.ca/en/employment-social-development/programs/laws-regulations/labour/interpretations-policies/medical-leave-pay.html", "https://www.canada.ca/en/services/jobs/workplace/federal-labour-standards/leaves.html"]}, {"id": "19-018", "chapter_num": 19, "chapter_title": "Jobs, dismissal, and work injuries", "chapter_file": "19-jobs-dismissal-injuries.md", "number": 18, "title": "Bullying at work: document, then use the channel that fits", "money": "0", "time": "mid", "willpower": "yes", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money. The cost is months of documenting: dates, witnesses, exact words, saved messages. Complaints and lawsuits take months.", "plain": "Workplace bullying is not a minor annoyance. Bullied workers faced about 59% higher cardiovascular risk in a study pooling three worker cohorts, and about double the odds of later suicidal thoughts in a Norwegian study. Canada has no single bullying statute, so use the channel that fits the conduct. Harassment tied to a protected ground is discrimination under human-rights law. Assaults and threats are police matters. Keep a written log from day one.", "benefit_text": "Xu et al. (2019): 79,201 workers, 12.4 years mean follow-up; bullying linked to about 59% higher cardiovascular-disease risk (HR 1.59, 95% CI 1.28–1.98); workplace violence about 25% higher (HR 1.25); dose-response in both. Nielsen et al. (2015): 1,846 Norwegian workers; bullied workers had about double the odds of later suicidal ideation (OR 2.05, 95% CI 1.08–3.89); reverse direction not found. Federal: CHRA s.14 — \"It is a discriminatory practice, in matters related to employment, to harass an individual on a prohibited ground of discrimination\"; sexual harassment deemed included (2026).", "sources": "https://doi.org/10.1093/eurheartj/ehy683 ; https://doi.org/10.2105/AJPH.2015.302855 ; https://laws-lois.justice.gc.ca/eng/acts/H-6/section-14.html", "notes": "Graded B: observational cohorts, self-reported bullying; the numbers show association, not a guaranteed individual outcome. Canadian channels: federal CHRA s.14 verified verbatim (2026); Ontario OHSA violence/harassment duties, Ontario Human Rights Code employment grounds, and Quebec LNT arts. 81.18–81.20 psychological harassment are UNVERIFIED at write time (labour.md #5). Benefit graded mid for the death dimension: relative risk differences above 20% with an indirect causal lever. Canada's national suicide crisis line is 9-8-8: https://www.canada.ca/en/public-health/news/2023/11/9-8-8-suicide-crisis-helpline.html", "urls": ["https://doi.org/10.1093/eurheartj/ehy683", "https://doi.org/10.2105/AJPH.2015.302855", "https://laws-lois.justice.gc.ca/eng/acts/H-6/section-14.html", "https://www.canada.ca/en/public-health/news/2023/11/9-8-8-suicide-crisis-helpline.html"]}, {"id": "20-001", "chapter_num": 20, "chapter_title": "Caring for a newborn", "chapter_file": "20-newborn-care.md", "number": 1, "title": "Put the baby to sleep on its back, on a bare mattress", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free. It takes some resolve to keep the crib bare when every store sells bumpers and blankets.", "plain": "Babies sleep safest on their backs, on a firm flat mattress, with nothing else in the crib: no pillows, no blankets, no bumpers, no toys. Face-down sleep raises the risk of sudden death during sleep.", "benefit_text": "The American Academy of Pediatrics 2022 safe-sleep guideline: about 3,500 infants die each year in the US from sleep-related causes. Back sleeping on a bare, firm, flat surface is the core protection; soft bedding and stomach sleeping raise the risk. DOI 10.1542/peds.2022-057990.", "sources": "https://doi.org/10.1542/peds.2022-057990", "notes": "", "urls": ["https://doi.org/10.1542/peds.2022-057990"]}, {"id": "20-002", "chapter_num": 20, "chapter_title": "Caring for a newborn", "chapter_file": "20-newborn-care.md", "number": 2, "title": "Get the hepatitis B shot on the provincial schedule — at birth if the mother carries the virus", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free, as part of the provincial infant vaccine program.", "plain": "Hepatitis B spreads from mother to child at birth and becomes a lifelong liver infection far more often in babies than in adults. Babies born to mothers who carry the virus get the vaccine plus protective antibodies at birth; everyone else follows the provincial schedule, which in most provinces starts the series at two months.", "benefit_text": "The Rourke Baby Record, following NACI: infants of HBsAg-positive mothers receive hepatitis B vaccine and hepatitis B immune globulin (HBIG) at birth; the routine infant series follows the provincial schedule, with most provinces giving the first dose at 2 months of age. Chronic infection develops in up to 90% of infected newborns, versus under 5% of infected adults — chronicity figures UNVERIFIED in this edition (not stated on the cited Rourke page; see docs/verification/spot-read.md).", "sources": "https://www.rourkebabyrecord.ca/interactive-guide/guide-4c/evidence/hep-b-vaccine", "notes": "", "urls": ["https://www.rourkebabyrecord.ca/interactive-guide/guide-4c/evidence/hep-b-vaccine"]}, {"id": "20-003", "chapter_num": 20, "chapter_title": "Caring for a newborn", "chapter_file": "20-newborn-care.md", "number": 3, "title": "Use the free provincial vaccine schedule; catch up on anything missed", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "C", "grade": "C", "disputed": false, "cost": "Free — every dose on the provincial schedule is publicly funded. The cost is the appointment time.", "plain": "Every province publishes a routine childhood vaccine schedule, and every dose on it is free. If a dose was missed — a move, an illness, a long wait — catch-up schedules exist at any age. Ask the local public health unit.", "benefit_text": "Statistics Canada's 2021 Childhood National Immunization Coverage Survey tracks uptake across the country; provinces fund all routine childhood vaccines at no charge to parents. Catch-up doses for children who fell behind: ask the local public health unit (catch-up availability is not stated in the cited survey).", "sources": "https://www150.statcan.gc.ca/n1/daily-quotidien/230612/dq230612b-eng.pdf", "notes": "", "urls": ["https://www150.statcan.gc.ca/n1/daily-quotidien/230612/dq230612b-eng.pdf"]}, {"id": "20-004", "chapter_num": 20, "chapter_title": "Caring for a newborn", "chapter_file": "20-newborn-care.md", "number": 4, "title": "Breastfeed exclusively for six months when you can", "money": "0", "time": "high", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free in money; expensive in time and effort, especially in the early weeks.", "plain": "When breastfeeding works for mother and baby, exclusive breastfeeding for about six months — nothing else, not even water — gives the baby the best-studied start. It protects against gut and chest infections and helps the mother recover too.", "benefit_text": "The World Health Organization recommends exclusive breastfeeding for the first 6 months of life, then continued breastfeeding with complementary foods up to 2 years and beyond. Breastfed infants have fewer gastrointestinal and respiratory infections.", "sources": "https://www.who.int/news-room/questions-and-answers/item/breastfeeding and https://www.who.int/news-room/fact-sheets/detail/infant-and-young-child-feeding", "notes": "", "urls": ["https://www.who.int/news-room/fact-sheets/detail/infant-and-young-child-feeding", "https://www.who.int/news-room/questions-and-answers/item/breastfeeding"]}, {"id": "20-005", "chapter_num": 20, "chapter_title": "Caring for a newborn", "chapter_file": "20-newborn-care.md", "number": 5, "title": "Make formula with water at 70°C or hotter", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free. It takes some care to get the temperature right every time.", "plain": "Powdered formula is not sterile; it can carry bacteria that are dangerous to newborns. Boil the water, let it cool just a little, and mix the powder while the water is still very hot — then cool the bottle to feeding temperature before offering it.", "benefit_text": "The WHO/FAO 2007 guidelines for powdered infant formula: reconstitute with water at 70°C or hotter to kill Cronobacter and Salmonella that can contaminate the powder; cool the prepared feed to a safe temperature before feeding.", "sources": "https://b5d7ac.staticwbm.com/20131021184456/http://www.who.int/foodsafety/publications/micro/pif_guidelines.pdf", "notes": "", "urls": ["https://b5d7ac.staticwbm.com/20131021184456/http://www.who.int/foodsafety/publications/micro/pif_guidelines.pdf"]}, {"id": "20-006", "chapter_num": 20, "chapter_title": "Caring for a newborn", "chapter_file": "20-newborn-care.md", "number": 6, "title": "Give no honey in the first year", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free — it is about withholding, not buying.", "plain": "Honey can contain the spores that cause infant botulism, and a baby's gut cannot stop them yet. No honey — not in a bottle, not on a soother — until the first birthday has passed.", "benefit_text": "The CDC: honey can contain Clostridium botulinum spores; infants under 12 months should not be given honey because their gut flora cannot suppress spore germination; infant botulism can cause paralysis and breathing failure.", "sources": "https://www.cdc.gov/botulism/prevention/", "notes": "", "urls": ["https://www.cdc.gov/botulism/prevention/"]}, {"id": "20-007", "chapter_num": 20, "chapter_title": "Caring for a newborn", "chapter_file": "20-newborn-care.md", "number": 7, "title": "Say yes to the vitamin K shot at birth", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free, given in the hospital before discharge.", "plain": "Newborns are born low in vitamin K, which blood needs to clot. One small injection at birth prevents a rare but devastating bleeding disorder of the newborn. Oral drops are a weaker substitute.", "benefit_text": "The Canadian Paediatric Society: vitamin K deficiency bleeding can cause brain bleeding in the first weeks of life; a single intramuscular dose at birth prevents it; oral vitamin K is less reliable and requires repeated doses.", "sources": "https://cps.ca/en/documents/position/Vitamin-k-prophylaxis-in-newborns", "notes": "", "urls": ["https://cps.ca/en/documents/position/Vitamin-k-prophylaxis-in-newborns"]}, {"id": "20-008", "chapter_num": 20, "chapter_title": "Caring for a newborn", "chapter_file": "20-newborn-care.md", "number": 8, "title": "Treat a fever in a baby under three months as an emergency", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "An emergency department visit — covered by provincial health insurance, but it costs a night of sleep.", "plain": "A rectal temperature of 38 degrees and up in a baby younger than three months is an emergency until proven otherwise. Newborns can go downhill fast, so skip the wait-and-see and go to the emergency department.", "benefit_text": "AAFP guidance on febrile infants: a rectal temperature of 38°C (100.4°F) or higher in an infant under 3 months requires same-day medical evaluation, usually in the emergency department, because serious bacterial infection cannot be ruled out at home.", "sources": "http://aafp.org/afp/2020/0615/p721.pdf", "notes": "", "urls": ["http://aafp.org/afp/2020/0615/p721.pdf"]}, {"id": "20-009", "chapter_num": 20, "chapter_title": "Caring for a newborn", "chapter_file": "20-newborn-care.md", "number": 9, "title": "Never shake a baby — not even in play", "money": "0", "time": "low", "willpower": "yes", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free. The price is self-control on the hardest nights.", "plain": "A baby's head is heavy and its neck is weak. Shaking — even a few seconds, even in play, even to wake a sleeping baby — can tear blood vessels in the brain and cause lifelong damage, even death. If the crying pushes you past your limit, put the baby down safely and walk away.", "benefit_text": "The Canadian Joint Statement on Shaken Baby Syndrome (Canadian Paediatric Society co-signatory, 2001): shaking an infant can cause subdural bleeding, brain injury, blindness, and death. A CMAJ randomized trial of the PURPLE crying parent-education program showed teaching parents about normal crying patterns reduces shaking.", "sources": "https://pmc.ncbi.nlm.nih.gov/articles/PMC2805972/ and https://www.cmaj.ca/content/180/7/727.abstract", "notes": "", "urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC2805972/", "https://www.cmaj.ca/content/180/7/727.abstract"]}, {"id": "20-010", "chapter_num": 20, "chapter_title": "Caring for a newborn", "chapter_file": "20-newborn-care.md", "number": 10, "title": "Introduce peanut early for babies at high allergy risk — with the doctor's guidance", "money": "low", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "A tube of peanut butter; possibly an allergy test first, covered by provincial insurance on referral.", "plain": "Babies with severe eczema and babies with an egg allergy are the most likely to develop peanut allergy. For them, feeding peanut in the first year — as smooth peanut butter thinned with water, never whole nuts — cut peanut allergy sharply in a landmark trial. Talk to the doctor first about testing and timing.", "benefit_text": "The LEAP trial (NEJM 2015): among high-risk infants, early peanut consumption reduced peanut allergy at age 5 by 81% relative to avoidance; guidelines now recommend early introduction for high-risk infants after medical evaluation. DOI 10.1056/NEJMoa1414850.", "sources": "https://doi.org/10.1056/NEJMoa1414850", "notes": "", "urls": ["https://doi.org/10.1056/NEJMoa1414850"]}, {"id": "20-011", "chapter_num": 20, "chapter_title": "Caring for a newborn", "chapter_file": "20-newborn-care.md", "number": 11, "title": "Register the birth and get the baby's health card in the first days", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "Free; birth registration and the newborn health card application cost nothing in Ontario.", "plain": "Ontario folds five steps into one: the birth registration, the birth certificate order, the newborn's health card application, and the federal child-benefit applications. Do it at the hospital before discharge if you can; if not, do it online in the first days, so the baby is covered from day one.", "benefit_text": "ServiceOntario's 5-in-1 Newborn Bundle lets parents register the birth, order a birth certificate, apply for the baby's OHIP card, and apply for federal benefits in one session; hospitals provide the infant registration form (Form 4440-82) carrying the baby's preprinted health number.", "sources": "http://www.ontario.ca/page/serviceontario and https://cdn-cms.f-static.net/uploads/4371791/normal_603a75fcebc0b.pdf", "notes": "", "urls": ["http://www.ontario.ca/page/serviceontario", "https://cdn-cms.f-static.net/uploads/4371791/normal_603a75fcebc0b.pdf"]}, {"id": "21-001", "chapter_num": 21, "chapter_title": "Travelling Abroad and Staying Safe", "chapter_file": "21-travelling-abroad.md", "number": 1, "title": "Buy travel medical insurance that covers evacuation before you leave", "money": "low", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "A modest premium per trip; minutes to buy online.", "plain": "Provincial health plans pay almost nothing for care outside Canada, so buy travel medical insurance for every trip abroad. Make sure the policy covers hospitalization, pre-existing conditions when you have them, medical evacuation, and repatriation of remains. Read the exclusions for adventure sports and alcohol before you rely on the policy.", "benefit_text": "A single air ambulance can cost more than most trips; insurance covering evacuation and repatriation keeps one accident from becoming a six-figure bill. (Cost figures are illustrative author estimates — the cited Government of Canada travel page gives no dollar amounts.)", "sources": "Government of Canada — advice for Canadian travellers: buy travel insurance — https://www.canada.ca/en/global-affairs/news/2019/01/advice-for-canadian-travellers-buy-travel-insurance.html", "notes": "Graded mid on money by judgement: the cited page gives no dollar amounts, so the grade rests on avoiding a large uninsured loss, not a verified figure.", "urls": ["https://www.canada.ca/en/global-affairs/news/2019/01/advice-for-canadian-travellers-buy-travel-insurance.html"]}, {"id": "21-002", "chapter_num": 21, "chapter_title": "Travelling Abroad and Staying Safe", "chapter_file": "21-travelling-abroad.md", "number": 2, "title": "Never lie on an immigration application — misrepresentation bans you for years", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; honesty and full disclosure.", "plain": "Lying on a visa, work permit, study permit, and permanent residence application — a fake job letter, a hidden refusal, and invented work history — is misrepresentation under the Immigration and Refugee Protection Act. The penalty is refusal plus a ban from entering Canada for at least five years, a permanent fraud record, and possible loss of status and criminal charges. Tell the truth and disclose refusals; a weak application refused honestly can be tried again.", "benefit_text": "One lie on an application triggers a minimum five-year ban from Canada and a permanent fraud record; honesty keeps every future application alive.", "sources": "IRCC Help Centre — misrepresentation — https://ircc.canada.ca/english/helpcentre/answer.asp?qnum=448&top=7", "notes": "", "urls": ["https://ircc.canada.ca/english/helpcentre/answer.asp?qnum=448&top=7"]}, {"id": "21-003", "chapter_num": 21, "chapter_title": "Travelling Abroad and Staying Safe", "chapter_file": "21-travelling-abroad.md", "number": 3, "title": "Save the consular emergency number before you fly", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a contact entry and a screenshot.", "plain": "Before leaving Canada, save the Emergency Watch and Response Centre number in your phone and share it with your travel companions. Consular officers can replace a lost passport, visit you when you are detained, and help your family reach you in a crisis. They cannot pay your bills, post bail, and get you out of jail — know the limits before you need them.", "benefit_text": "The 24/7 Emergency Watch and Response Centre (+1 613-996-8885, call collect where available; sos@international.gc.ca; SMS +1 613-686-3658; WhatsApp +1 613-909-8881) is the lifeline when the local Canadian office is closed.", "sources": "Global Affairs Canada — consular assistance, emergency info — https://travel.gc.ca/assistance/emergency-info", "notes": "Emergency consular loans are a last resort and must be repaid.", "urls": ["https://travel.gc.ca/assistance/emergency-info"]}, {"id": "21-004", "chapter_num": 21, "chapter_title": "Travelling Abroad and Staying Safe", "chapter_file": "21-travelling-abroad.md", "number": 4, "title": "Check the four-level travel advisory for your destination", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a few minutes on the advisory page.", "plain": "Read the Government of Canada travel advisory for every country on your itinerary before booking. Advisories run through four levels, from normal precautions to avoid all travel. Insurance often stops paying at the higher levels, and airlines may cancel. Signing up for the traveller registry lets Ottawa reach you when the level changes mid-trip.", "benefit_text": "The four advisory levels (travel.gc.ca/travelling/advisories) decide whether your insurance pays; checking before booking avoids paying for a trip you must cancel yourself.", "sources": "Government of Canada — travel advice and advisories — https://travel.gc.ca/travelling/advisories", "notes": "", "urls": ["https://travel.gc.ca/travelling/advisories"]}, {"id": "21-005", "chapter_num": 21, "chapter_title": "Travelling Abroad and Staying Safe", "chapter_file": "21-travelling-abroad.md", "number": 5, "title": "Register with Registration of Canadians Abroad", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; a few minutes online.", "plain": "Sign up for the free Registration of Canadians Abroad service before you leave, and add every country on your itinerary. The government uses your contact details to send safety alerts and to reach you during natural disasters and civil unrest. Registration is confidential and takes a few minutes online.", "benefit_text": "ROCA is free and confidential; in a crisis it lets consular teams find you and push evacuation information to your phone.", "sources": "Government of Canada — Registration of Canadians Abroad — https://travel.gc.ca/travelling/registration", "notes": "", "urls": ["https://travel.gc.ca/travelling/registration"]}, {"id": "21-006", "chapter_num": 21, "chapter_title": "Travelling Abroad and Staying Safe", "chapter_file": "21-travelling-abroad.md", "number": 6, "title": "Declare everything at customs and report cash of ten thousand dollars and more", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Nothing; honesty at the kiosk.", "plain": "When returning to Canada, declare all goods you bought and received abroad. Cash and monetary instruments of ten thousand Canadian dollars and more must be reported to border officers — reporting is not taxed, but failing to report brings seizure and fines. Know your exemption before you shop: no exemption for same-day trips, two hundred dollars after a day away, and eight hundred after two days away.", "benefit_text": "Declaring everything and reporting CAN$10,000 and more avoids seizure and fines; the $200 (over-24-hour) and $800 (over-48-hour and 7-day) exemptions set your duty-free shopping ceiling.", "sources": "CBSA — declare goods — https://www.cbsa-asfc.gc.ca/travel-voyage/declare-eng.html", "notes": "", "urls": ["https://www.cbsa-asfc.gc.ca/travel-voyage/declare-eng.html"]}]);
